import java.util.*;class Solution{Map<String,List<Object[]>>g=new HashMap<>();double f(String u,String t,Set<String>v){if(!g.containsKey(u))return-1;if(u.equals(t))return 1;v.add(u);for(Object[]e:g.get(u)){String x=(String)e[0];double w=(double)e[1];if(!v.contains(x)){double r=f(x,t,v);if(r>0)return w*r;}}return-1;}public double[] calcEquation(List<List<String>>e,double[]val,List<List<String>>q){for(int i=0;i<e.size();i++){String a=e.get(i).get(0),b=e.get(i).get(1);g.computeIfAbsent(a,k->new ArrayList<>()).add(new Object[]{b,val[i]});g.computeIfAbsent(b,k->new ArrayList<>()).add(new Object[]{a,1.0/val[i]});}double[]o=new double[q.size()];for(int i=0;i<q.size();i++)o[i]=f(q.get(i).get(0),q.get(i).get(1),new HashSet<>());return o;}}
